function onSquare(e){if(finished)return;let y=+e.currentTarget.dataset.y,x=+e.currentTarget.dataset.x,p=game.b[y][x];if(selected){let m=legalFrom.find(m=>m.to.y===y&&m.to.x===x);if(m){if(m.promotion){showPromotion(m);return}playMove(m);return}}if(p&&p.c===game.turn){selected={y,x};legalFrom=legalMoves(game,y,x)}else{selected=null;legalFrom=[]}render()}
function playMove(m,promo='q'){let before=clone(game),piece=game.b[m.from.y][m.from.x],color=piece.c,san=sanFor(game,m),captured=apply(game,m,promo);lastMove={from:m.from,to:m.to};history.push({before,move:m,san,captured:captured?{...captured}:null,color,key:positionKey(game)});selected=null;legalFrom=[];finished=false;checkEnd();render()}
