function undo(){if(!history.length)return;let h=history.pop();game=h.before;lastMove=history.length?history[history.length-1].move:null;finished=false;selected=null;legalFrom=[];render()}
function reset(){game=makeInitial();history=[];selected=null;legalFrom=[];lastMove=null;finished=false;render()}
document.getElementById('newGameBtn').addEventListener('click',reset);document.getElementById('undoBtn').addEventListener('click',undo);document.getElementById('flipBtn').addEventListener('click',()=>{flipped=!flipped;render()});game=makeInitial();render();
</script></body>

